CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin','owner','developer')));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.account_controls (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','frozen','banned','deleted')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_controls TO authenticated; GRANT ALL ON public.account_controls TO service_role;
ALTER TABLE public.account_controls ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_status ON public.account_controls FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.account_can_read() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.account_controls WHERE user_id=auth.uid() AND status IN ('suspended','banned','deleted')) $$;
CREATE FUNCTION public.account_can_write() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.account_controls WHERE user_id=auth.uid() AND status <> 'active') $$;
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, target_id uuid, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_audit TO service_role; ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.contact_discovery (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contact_discovery TO authenticated; GRANT ALL ON public.contact_discovery TO service_role;
ALTER TABLE public.contact_discovery ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_discovery ON public.contact_discovery FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.match_contacts(emails text[]) RETURNS TABLE(id uuid,display_name text,username text, matched_email text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.username,lower(u.email) FROM public.profiles p JOIN auth.users u ON u.id=p.id JOIN public.contact_discovery d ON d.user_id=p.id AND d.enabled WHERE auth.uid() IS NOT NULL AND public.account_can_read() AND u.email_confirmed_at IS NOT NULL AND lower(u.email)=ANY(emails[1:200]) AND NOT EXISTS(SELECT 1 FROM public.account_controls a WHERE a.user_id=p.id AND a.status IN ('banned','deleted','suspended')) $$;
REVOKE ALL ON FUNCTION public.match_contacts(text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.match_contacts(text[]) TO authenticated;
CREATE TABLE public.marketplace_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seller_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL CHECK(price>=0), currency text NOT NULL DEFAULT 'PKR' CHECK(currency IN ('PKR','USD')), category text NOT NULL, location text NOT NULL DEFAULT '', image_path text, status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','sold')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.marketplace_listings TO authenticated; GRANT ALL ON public.marketplace_listings TO service_role;
ALTER TABLE public.marketplace_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_listings ON public.marketplace_listings FOR SELECT TO authenticated USING(true);
CREATE POLICY own_listings ON public.marketplace_listings FOR ALL TO authenticated USING(seller_id=auth.uid()) WITH CHECK(seller_id=auth.uid());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','follows','conversation_members','conversations','messages','posts','post_media','post_likes','post_bookmarks','comments','stories','story_views','reels','reel_likes','reel_comments','videos','video_likes','video_bookmarks','subscriptions','marketplace_listings','contact_discovery'] LOOP EXECUTE format('CREATE POLICY account_read_guard ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING(public.account_can_read())',t); EXECUTE format('CREATE POLICY account_insert_guard ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.account_can_write())',t); EXECUTE format('CREATE POLICY account_update_guard ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.account_can_write()) WITH CHECK(public.account_can_write())',t); EXECUTE format('CREATE POLICY account_delete_guard ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING(public.account_can_write())',t); END LOOP; END $$;
CREATE POLICY account_storage_insert_guard ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.account_can_write());
CREATE POLICY account_storage_update_guard ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.account_can_write()) WITH CHECK(public.account_can_write());
CREATE POLICY account_storage_delete_guard ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(public.account_can_write());